import tempfile
from pathlib import Path
from types import SimpleNamespace
from evolving_agent.model import ModelReply, ToolCall
from evolving_agent.session import Deadline, ToolAgentSession

class Model:
    def __init__(self): self.calls=[]
    def reply(self, *, conversation, tools=()):
        self.calls.append((list(conversation), tuple(tools)))
        n=len(self.calls)
        if n==1:
            return ModelReply('I put the program below.', (), ({'role':'assistant','content':'I put the program below.'},))
        if n==2:
            assert 'without creating a deliverable' in conversation[-1]['content']
            return ModelReply('', (ToolCall('w1','write_file','{"path":"output/solution.py","content":"print(42)"}'),), ({'type':'function_call','call_id':'w1','name':'write_file','arguments':'{}'},))
        return ModelReply('Created and checked output/solution.py.', (), ({'role':'assistant','content':'done'},))
class Tools:
    def __init__(self, root): self.root=root
    def call(self, name, args):
        target=self.root/'solution.py'; target.write_text('print(42)\n')
        return SimpleNamespace(text='wrote output/solution.py',is_error=False)

with tempfile.TemporaryDirectory() as d:
    out=Path(d); (out/'.meta').mkdir(); (out/'.meta'/'trace.json').write_text('{}')
    model=Model(); session=ToolAgentSession(model,Tools(out),[],deadline=Deadline(30),max_steps=5,deliverables=out)
    result=session.run(instructions='system',opening='create output/solution.py')
    assert result.finished and result.steps==3, result
    assert (out/'solution.py').read_text()=='print(42)\n'
    assert len(model.calls)==3
    print('PASS: prose-only completion was rejected despite .meta; reminder caused write_file and session completed after artifact existed')

